const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const n = parseInt(input.trim(), 10);

    if (n % 4 === 0 || n % 4 === 3) {
        console.log("0");
    } else {
        console.log("1");
    }

    rl.close();
});

